// Cardio tracking index — record JAH-GAI-BPMONITOR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"accuracy_pct": 99, "memory_readings": 120, "price_usd": 100};
var value = (m.accuracy_pct*m.memory_readings/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAI-BPMONITOR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAI-BPMONITOR-000001|' + value.toFixed(2) + ' tracking index');

